import React from 'react';
import {AbsoluteFill, interpolate, useCurrentFrame} from 'remotion';
import {FONT_FAMILY} from '../constants';

// 2.5D 拓扑词：SVG 连线 + 节点 + 文字复制层偏移
const NODES = [
  {x: 300, y: 130, label: '制造工艺', size: 26},
  {x: 620, y: 60, label: '风险监测', size: 22},
  {x: 640, y: 300, label: '持续追踪', size: 24},
  {x: 320, y: 380, label: '专利变化', size: 20},
  {x: 120, y: 250, label: '技术推进', size: 20},
];

const LINKS: [number, number][] = [
  [0, 1],
  [0, 2],
  [0, 3],
  [1, 4],
  [2, 3],
];

export const TopologyWords: React.FC<{title: string}> = ({title}) => {
  const frame = useCurrentFrame();

  return (
    <AbsoluteFill style={{justifyContent: 'center', alignItems: 'center'}}>
      {/* 主标题 */}
      <div
        style={{
          fontFamily: FONT_FAMILY,
          fontSize: 64,
          fontWeight: 800,
          color: '#17306b',
          letterSpacing: 4,
          textShadow: '0 6px 30px rgba(120,150,255,0.35)',
          position: 'relative',
          zIndex: 5,
        }}
      >
        {title}
      </div>

      {/* SVG 拓扑网络 */}
      <svg
        width={780}
        height={480}
        viewBox="0 0 780 480"
        style={{position: 'absolute', inset: 0, margin: 'auto', zIndex: 2}}
      >
        {LINKS.map(([a, b], i) => {
          const na = NODES[a];
          const nb = NODES[b];
          const appear = interpolate(frame, [10 + i * 4, 20 + i * 4], [0, 1], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          });
          return (
            <line
              key={i}
              x1={na.x + 120}
              y1={na.y}
              x2={nb.x + 120}
              y2={nb.y}
              stroke="rgba(90,120,230,0.55)"
              strokeWidth={1.6}
              strokeDasharray="6 6"
              opacity={0.75 * appear}
            />
          );
        })}
        {NODES.map((n, i) => {
          const appear = interpolate(frame, [14 + i * 5, 26 + i * 5], [0, 1], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          });
          const drift = interpolate(frame, [0, 90], [0, i % 2 === 0 ? -5 : 5], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          });
          return (
            <g
              key={i}
              transform={`translate(0 ${drift})`}
              style={{opacity: appear}}
            >
              <circle cx={n.x + 120} cy={n.y} r={7} fill="#6d8dff" opacity={0.85} />
              <circle
                cx={n.x + 120}
                cy={n.y}
                r={14}
                fill="none"
                stroke="#8fa8ff"
                strokeWidth={1.2}
                opacity={0.6}
              />
              {/* 2.5D 偏移层 */}
              <text
                x={n.x + 120 + 2.4}
                y={n.y + 2.4}
                fontSize={n.size}
                fontWeight={700}
                fill="rgba(70,90,190,0.30)"
                textAnchor="middle"
                dominantBaseline="middle"
              >
                {n.label}
              </text>
              <text
                x={n.x + 120}
                y={n.y}
                fontSize={n.size}
                fontWeight={700}
                fill="#2b3f7e"
                textAnchor="middle"
                dominantBaseline="middle"
                style={{fontFamily: FONT_FAMILY}}
              >
                {n.label}
              </text>
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

import React from 'react';
import {Img, Video, staticFile} from 'remotion';
import {ASSETS} from '../constants';

// 透明电脑画中画：demo 视频裁进屏幕区域（x 22–78%, y 22–68%）
export const LaptopDemo: React.FC<{
  src: string;
  style?: React.CSSProperties;
  videoStyle?: React.CSSProperties;
}> = ({src, style, videoStyle}) => {
  return (
    <div style={{position: 'relative', ...style}}>
      <Img
        src={staticFile(ASSETS.laptop)}
        style={{width: '100%', height: '100%', objectFit: 'contain', display: 'block'}}
      />
      <div
        style={{
          position: 'absolute',
          left: '22.4%',
          top: '21.6%',
          width: '55.4%',
          height: '46.4%',
          overflow: 'hidden',
          borderRadius: 8,
          background: '#0b1533',
          boxShadow: 'inset 0 0 0 1.5px rgba(255,255,255,0.35)',
          ...videoStyle,
        }}
      >
        <Video
          src={src}
          muted
          style={{width: '100%', height: '100%', objectFit: 'cover'}}
        />
      </div>
    </div>
  );
};

import React from 'react';
import {AbsoluteFill, interpolate, useCurrentFrame} from 'remotion';
import {FONT_FAMILY} from '../constants';

// 程序化数字卡/关键词卡：按 cue 依次出现
export const DataCard: React.FC<{
  value: string;
  label?: string;
  appearAt: number; // 帧
  accent?: string;
  width?: number;
}> = ({value, label, appearAt, accent = '#4f6ef7', width = 250}) => {
  const frame = useCurrentFrame();
  const opacity = interpolate(frame, [appearAt, appearAt + 8], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const scale = interpolate(frame, [appearAt, appearAt + 10], [0.82, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const y = interpolate(frame, [appearAt, appearAt + 10], [22, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  return (
    <div
      style={{
        width,
        fontFamily: FONT_FAMILY,
        background: 'rgba(255,255,255,0.9)',
        borderRadius: 16,
        padding: '14px 18px',
        boxShadow: '0 8px 28px rgba(70,100,220,0.18)',
        borderLeft: `5px solid ${accent}`,
        opacity,
        transform: `translateY(${y}px) scale(${scale})`,
      }}
    >
      <div
        style={{
          fontSize: 40,
          fontWeight: 800,
          color: accent,
          lineHeight: 1.1,
        }}
      >
        {value}
      </div>
      {label ? (
        <div
          style={{
            fontSize: 20,
            fontWeight: 600,
            color: '#33406b',
            marginTop: 4,
          }}
        >
          {label}
        </div>
      ) : null}
    </div>
  );
};

export const KeywordPill: React.FC<{
  text: string;
  appearAt: number;
  index: number;
}> = ({text, appearAt, index}) => {
  const frame = useCurrentFrame();
  const opacity = interpolate(frame, [appearAt, appearAt + 8], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const x = interpolate(frame, [appearAt, appearAt + 10], [36, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  return (
    <div
      style={{
        fontFamily: FONT_FAMILY,
        fontSize: 26,
        fontWeight: 700,
        color: '#2b3f7e',
        background: 'rgba(255,255,255,0.92)',
        borderRadius: 999,
        padding: '10px 26px',
        boxShadow: '0 6px 20px rgba(70,100,220,0.16)',
        opacity,
        transform: `translateX(${x}px)`,
        display: 'flex',
        alignItems: 'center',
        gap: 10,
      }}
    >
      <span
        style={{
          width: 10,
          height: 10,
          borderRadius: 999,
          background: ['#4f6ef7', '#7c5cf0', '#2ea8c8', '#e08a3c', '#4f9d5f'][index % 5],
          display: 'inline-block',
        }}
      />
      {text}
    </div>
  );
};

export const VStack: React.FC<{
  children: React.ReactNode;
  style?: React.CSSProperties;
}> = ({children, style}) => (
  <AbsoluteFill style={{justifyContent: 'center', alignItems: 'flex-start', ...style}}>
    <div style={{display: 'flex', flexDirection: 'column', gap: 18}}>{children}</div>
  </AbsoluteFill>
);

import React from 'react';
import {
  AbsoluteFill,
  Audio,
  Img,
  interpolate,
  Loop,
  Sequence,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';
import {ASSETS, FPS, SCENES, VO_SEGMENTS} from './constants';
import {Background} from './components/Background';
import {GreenScreenPresenter} from './components/GreenScreenPresenter';
import {LaptopDemo} from './components/LaptopDemo';
import {SemanticCaption} from './components/SemanticCaption';
import {TopologyWords} from './components/TopologyWords';
import {DataCard, KeywordPill, VStack} from './components/DataCards';

// ---------- BGM Ducking ----------
const bgmVolume = (frame: number): number => {
  const t = frame / FPS;
  let v = 0.5;
  for (const seg of VO_SEGMENTS) {
    const target = seg.lift ? 0.4 : 0.22;
    const attackStart = seg.s - 0.25;
    const releaseEnd = seg.e + 0.5;
    if (t >= seg.s && t <= seg.e) {
      v = Math.min(v, target);
    } else if (t >= attackStart && t < seg.s) {
      const k = (t - attackStart) / 0.25;
      v = Math.min(v, 0.5 + (target - 0.5) * k);
    } else if (t > seg.e && t <= releaseEnd) {
      const k = (t - seg.e) / 0.5;
      v = Math.min(v, target + (0.5 - target) * k);
    }
  }
  if (t < 1) v *= t; // fade in
  if (t > 82) v *= Math.max(0, (84 - t) / 2); // fade out
  return v;
};

// ---------- 数字人布局 ----------
const PRESENTER_STYLE: React.CSSProperties = {
  position: 'absolute',
  left: 30,
  top: 250,
  width: 620,
  height: 660,
};

const presenterLoopFrames = Math.round(10.01 * FPS); // ≈300

// ---------- 场景 S01：Hook ----------
const S01: React.FC = () => {
  const frame = useCurrentFrame();
  const enter = interpolate(frame, [0, 12], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const presenterStyle: React.CSSProperties = {
    ...PRESENTER_STYLE,
    opacity: enter,
    transform: `translateY(${(1 - enter) * 26}px)`,
  };
  return (
    <AbsoluteFill>
      <Background src={ASSETS.bgFlow} />
      <Loop durationInFrames={presenterLoopFrames}>
        <GreenScreenPresenter src={staticFile(ASSETS.presenter)} style={presenterStyle} />
      </Loop>
      <div
        style={{
          position: 'absolute',
          right: 120,
          top: 0,
          width: 900,
          height: 1080,
        }}
      >
        <TopologyWords title="制造工艺专利监测" />
      </div>
      <SemanticCaption text="变化，要更早看见" delay={1.6} duration={5.6} />
      <Audio src={staticFile(ASSETS.vo.vo01)} />
    </AbsoluteFill>
  );
};

// ---------- 场景 S02~S05：Demo 步骤 ----------
const DemoScene: React.FC<{
  demo: string;
  caption: string;
  captionDelay?: number;
  laptopScale?: [number, number];
  laptopCenter?: boolean; // S05：放大至中心
  presenterExit?: boolean; // S05：数字人淡出
  extra?: React.ReactNode;
  presenterOpacity?: number;
}> = ({
  demo,
  caption,
  captionDelay = 0.4,
  laptopScale = [0.96, 1],
  laptopCenter = false,
  presenterExit = false,
  extra,
  presenterOpacity = 1,
}) => {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const scaleIn = interpolate(frame, [0, 16], laptopScale, {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  // 数字人淡出（S05 最后 15 帧）
  let pOpacity = presenterOpacity;
  if (presenterExit) {
    const exitStart = durationInFrames - 15;
    pOpacity = interpolate(frame, [exitStart, durationInFrames], [presenterOpacity, 0], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });
  }

  // 电脑放大至中心（S05）
  const laptopStyle: React.CSSProperties = laptopCenter
    ? {
        position: 'absolute',
        left: interpolate(frame, [0, durationInFrames], [900, 400], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
        }),
        top: interpolate(frame, [0, durationInFrames], [250, 130], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
        }),
        width: interpolate(frame, [0, durationInFrames], [930, 1120], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
        }),
        height: interpolate(frame, [0, durationInFrames], [620, 746], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
        }),
        transform: `scale(${scaleIn})`,
        transformOrigin: 'center center',
      }
    : {
        position: 'absolute',
        left: 900,
        top: 250,
        width: 930,
        height: 620,
        transform: `scale(${scaleIn})`,
        transformOrigin: 'center center',
      };

  const presenterStyle: React.CSSProperties = {
    ...PRESENTER_STYLE,
    opacity: pOpacity,
  };

  return (
    <AbsoluteFill>
      <Background src={ASSETS.bgFlow} />
      <Loop durationInFrames={presenterLoopFrames}>
        <GreenScreenPresenter src={staticFile(ASSETS.presenter)} style={presenterStyle} />
      </Loop>
      <LaptopDemo src={demo} style={laptopStyle} />
      {extra}
      <SemanticCaption text={caption} delay={captionDelay} />
      <Audio src={staticFile(ASSETS.vo.vo01)} />
    </AbsoluteFill>
  );
};

// S03 短词
const S03Words: React.FC = () => {
  const frame = useCurrentFrame();
  const words = ['制造工艺', '监测范围', '关注方向'];
  const appearAt = [0.9, 1.7, 2.5].map((s) => s * FPS);
  return (
    <div
      style={{
        position: 'absolute',
        right: 1180,
        top: 520,
        display: 'flex',
        flexDirection: 'column',
        gap: 22,
        alignItems: 'flex-start',
      }}
    >
      {words.map((w, i) => {
        const opacity = interpolate(frame, [appearAt[i], appearAt[i] + 8], [0, 1], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
        });
        const y = interpolate(frame, [appearAt[i], appearAt[i] + 10], [18, 0], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
        });
        return (
          <div
            key={w}
            style={{
              fontFamily: "'Noto Sans CJK SC', sans-serif",
              fontSize: 30,
              fontWeight: 700,
              color: '#2b3f7e',
              background: 'rgba(255,255,255,0.9)',
              borderRadius: 14,
              padding: '10px 22px',
              boxShadow: '0 6px 20px rgba(70,100,220,0.16)',
              opacity,
              transform: `translateY(${y}px)`,
            }}
          >
            {w}
          </div>
        );
      })}
    </div>
  );
};

// S04 状态标签
const S04Status: React.FC = () => {
  const frame = useCurrentFrame();
  const opacity = interpolate(frame, [12, 22], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  return (
    <div
      style={{
        position: 'absolute',
        right: 150,
        top: 300,
        fontFamily: "'Noto Sans CJK SC', sans-serif",
        fontSize: 26,
        fontWeight: 700,
        color: '#ffffff',
        background: 'linear-gradient(135deg, #4f6ef7, #7c5cf0)',
        borderRadius: 999,
        padding: '12px 26px',
        boxShadow: '0 8px 26px rgba(90,100,240,0.35)',
        opacity,
        display: 'flex',
        alignItems: 'center',
        gap: 10,
      }}
    >
      <span
        style={{
          width: 12,
          height: 12,
          borderRadius: 999,
          background: '#fff',
          animation: 'none',
        }}
      />
      AI 检索分析中
    </div>
  );
};

// ---------- 报告场景 ----------
const ReportScene: React.FC<{
  report: string;
  zoom?: number;
  panX?: number; // 百分比平移
  children?: React.ReactNode;
}> = ({report, zoom = 1.05, panX = 0, children}) => {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const scale = interpolate(frame, [0, durationInFrames], [1, zoom], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const translateX = interpolate(frame, [0, durationInFrames], [0, panX], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  return (
    <AbsoluteFill style={{background: '#eef1fb'}}>
      <div
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          overflow: 'hidden',
        }}
      >
        <Img
          src={staticFile(report)}
          style={{
            height: '96%',
            objectFit: 'contain',
            transform: `scale(${scale}) translateX(${translateX}%)`,
            boxShadow: '0 12px 48px rgba(40,60,140,0.22)',
            borderRadius: 8,
            background: '#fff',
          }}
        />
      </div>
      {children}
    </AbsoluteFill>
  );
};

// S06 数字卡
const S06Cards: React.FC = () => {
  const frame = useCurrentFrame();
