    </VStack>
  );
};

// S08 行动卡
const S08Cards: React.FC = () => {
  const frame = useCurrentFrame();
  const items = [
    {t: '扩展检索', d: '扩大技术方向与地域'},
    {t: '权利核验', d: '法律状态与权利要求'},
    {t: 'FTO 查新', d: '自由实施风险排查'},
    {t: '差异化证据', d: '补齐证据缺口'},
