  const cue = [0.8, 2.2, 3.7, 5.2].map((s) => s * FPS);
  return (
    <VStack style={{left: 1180, top: 0}}>
      {items.map((it, i) => {
        const opacity = interpolate(frame, [cue[i], cue[i] + 8], [0, 1], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
        });
        const y = interpolate(frame, [cue[i], cue[i] + 10], [20, 0], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
