        return (
          <div
            key={it.t}
            style={{
              width: 320,
              fontFamily: "'Noto Sans CJK SC', sans-serif",
              background: 'rgba(255,255,255,0.92)',
              borderRadius: 16,
              padding: '14px 20px',
              boxShadow: '0 8px 26px rgba(70,100,220,0.16)',
              borderLeft: '5px solid #4f6ef7',
              opacity,
              transform: `translateY(${y}px)`,
